  cast(null as timestamp) as run_started_at,
  cast(null as string) as endpoint,
  cast(null as struct<`request_kind` string, `location_code` int64, `language_code` string, `order_by` array<string>, `filters` string, `row_start` int64, `row_count` int64>) as run_settings,
  cast(null as int64) as call_index,
  cast(null as int64) as call_row_index,
  cast(null as int64) as call_offset,
  cast(null as int64) as call_total_count,
  cast(null as float64) as request_cost_usd,
  cast(null as int64) as location_code,
  cast(null as string) as language_code,
  cast(null as string) as keyword,
  cast(null as timestamp) as data_as_of,
  cast(null as struct<`se_type` string, `keyword` string, `location_code` int64, `language_code` string, `keyword_info` struct<`se_type` string, `last_updated_time` string, `competition` float64, `competition_level` string, `cpc` float64, `search_volume` int64, `low_top_of_page_bid` float64, `high_top_of_page_bid` float64, `categories` array<int64>, `monthly_searches` array<struct<`year` int64, `month` int64, `search_volume` int64>>, `search_volume_trend` struct<`monthly` int64, `quarterly` int64, `yearly` int64>>, `keyword_info_normalized_with_bing` struct<`search_volume` int64, `last_updated_time` string, `is_normalized` bool>, `keyword_info_normalized_with_clickstream` struct<`search_volume` int64, `last_updated_time` string, `is_normalized` bool>, `clickstream_keyword_info` struct<`search_volume` int64, `last_updated_time` string>, `keyword_properties` struct<`se_type` string, `core_keyword` string, `synonym_clustering_algorithm` string, `keyword_difficulty` int64, `detected_language` string, `is_another_language` bool>, `serp_info` struct<`se_type` string, `check_url` string, `serp_item_types` array<string>, `se_results_count` int64, `last_updated_time` string, `previous_updated_time` string>, `avg_backlinks_info` struct<`se_type` string, `backlinks` float64, `dofollow` float64, `referring_pages` float64, `referring_domains` float64, `referring_main_domains` float64, `rank` float64, `main_domain_rank` float64, `last_updated_time` string>, `search_intent_info` struct<`se_type` string, `main_intent` string, `foreign_intent` array<string>, `last_updated_time` string>>) as keyword_data,
  cast(null as struct<`se_type` string, `serp_item` struct<`se_type` string, `type` string, `rank_group` int64, `rank_absolute` int64, `position` string, `xpath` string, `domain` string, `title` string, `url` string, `breadcrumb` string, `website_name` string, `is_image` bool, `is_video` bool, `is_featured_snippet` bool, `is_malicious` bool, `checks` array<string>, `description` string, `pre_snippet` string, `extended_snippet` string, `amp_version` bool, `rating` struct<`rating_type` string, `value` float64, `votes_count` int64, `rating_max` float64>, `highlighted` array<string>, `links` array<struct<`type` string, `title` string, `description` string, `url` string, `domain` string, `ad_aclk` string, `xpath` string>>, `about_this_result` struct<`type` string, `url` string, `source` string, `source_info` string, `source_url` string, `language` string, `location` string, `search_terms` array<string>, `related_terms` array<string>>, `main_domain` string, `relative_url` string, `etv` float64, `estimated_paid_traffic_cost` float64, `clickstream_etv` int64, `rank_changes` struct<`previous_rank_absolute` int64, `is_new` bool, `is_up` bool, `is_down` bool>, `backlinks_info` struct<`referring_domains` int64, `referring_main_domains` int64, `referring_pages` int64, `dofollow` int64, `backlinks` int64, `time_update` string>, `rank_info` struct<`page_rank` int64, `main_domain_rank` int64>>, `check_url` string, `serp_item_types` array<string>, `se_results_count` int64, `keyword_difficulty` int64, `is_lost` bool, `last_updated_time` string, `previous_updated_time` string>) as ranked_serp_element
